import copy
import json
from pathlib import Path
import unittest

from services.evidence_scope import (require_source_need, encoded,
    require_dependency_versions, require_dependency_vocabulary)
from tests.test_candidate_comparison import candidate_facts
from tests.test_qualified_combat import row


class DependencyVersionTests(unittest.TestCase):
    def test_persisted_baseline_v3_round_trip_preserves_identity(self):
        # Generated by f3000e2's unmodified modules, not relabeled v4 output.
        raw=(Path(__file__).parent/'fixtures/dependency_source_v3.json').read_text()
        value=json.loads(raw)
        self.assertEqual(value['source_identity']['dependency_model_version'],'3')
        self.assertEqual(encoded(require_source_need(value)),encoded(value))

    def test_current_v4_source_round_trip(self):
        value=candidate_facts()['per_need'][0]['source_need']
        self.assertEqual(value['source_identity']['dependency_model_version'],'4')
        self.assertEqual(require_source_need(json.loads(json.dumps(value))),value)

    def test_unknown_and_malformed_versions_rejected(self):
        value=json.loads((Path(__file__).parent/'fixtures/dependency_source_v3.json').read_text())
        for version in ('2','5',4,True,None):
            bad=copy.deepcopy(value);bad['source_identity']['dependency_model_version']=version
            with self.assertRaises(ValueError):require_source_need(bad)
        for key in ('analysis_version','needs_model_version'):
            bad=copy.deepcopy(value);bad['source_identity'][key]='4'
            with self.assertRaises(ValueError):require_source_need(bad)

    def test_v4_semantics_rejected_under_v3_without_relabeling(self):
        features=row()['features']
        for feature in features:
            if feature['rule_id'] in ('intrinsic.creature_deathtouch.v1','trigger.qualified_poison.v1'):
                with self.assertRaises(ValueError):require_dependency_vocabulary(feature,'3')
                require_dependency_vocabulary(feature,'4')

    def test_both_versions_still_reject_malformed_source(self):
        old=json.loads((Path(__file__).parent/'fixtures/dependency_source_v3.json').read_text())
        new=candidate_facts()['per_need'][0]['source_need']
        for value in (old,new):
            bad=copy.deepcopy(value);bad['existing_side']['copy_count']=True
            with self.assertRaises(ValueError):require_source_need(bad)
            bad=copy.deepcopy(value);bad['unexpected']=True
            with self.assertRaises(ValueError):require_source_need(bad)
